import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "किसी को डॉक्टर ने एक्स रे लिखा, किसी को सी टी स्कैन, और किसी को एम आर आई. तीनों में फर्क क्या है? और डॉक्टर कब कौन सी जांच कहते हैं? आखिर तक देखिए.",
 "एक्स रे में, बहुत कम मात्रा की एक्स रे किरणें शरीर से गुज़रती हैं. हड्डी सफेद दिखती है. यह एक सीधी, दो डी तस्वीर है, और कुछ ही सेकंड लगते हैं. छाती के एक्स रे का रेडिएशन, लगभग दस दिन की प्राकृतिक रेडिएशन जितना होता है.",
 "एक्स रे कब? हड्डी टूटने का शक. छाती में इन्फेक्शन, निमोनिया, या टी बी का शक. दांत की जांच. और जोड़ों का गठिया. यह अक्सर पहली, जल्दी होने वाली, और सस्ती जांच होती है.",
 "सी टी स्कैन भी एक्स रे से होता है, पर मशीन शरीर के चारों ओर घूमती है. कंप्यूटर, शरीर की ब्रेड के स्लाइस जैसी परतें बनाता है. स्कैन कुछ मिनट में हो जाता है. पर रेडिएशन ज़्यादा है. पेट के सी टी में, लगभग ढाई साल की प्राकृतिक रेडिएशन जितना.",
 "सी टी कब? इमरजेंसी में. सिर की चोट. स्ट्रोक में, दिमाग में ब्लीडिंग देखने के लिए. एक्सीडेंट में अंदरूनी चोट. अचानक तेज़ पेट दर्द, और किडनी स्टोन. कभी कभी कंट्रास्ट इंजेक्शन दिया जाता है, इसलिए एलर्जी या किडनी की बीमारी हो, तो पहले बताएं.",
 "एम आर आई में, तेज़ चुंबक और रेडियो तरंगें इस्तेमाल होती हैं. इसमें एक्स रे वाली रेडिएशन नहीं होती. यह नरम टिशू को बहुत बारीकी से दिखाता है. स्कैन में आमतौर पर बीस से चालीस मिनट लगते हैं, और मशीन तेज़ आवाज़ करती है.",
 "एम आर आई कब? दिमाग और रीढ़ की हड्डी की बीमारियां. स्लिप डिस्क. घुटने और कंधे के लिगामेंट की चोट. नसों की समस्या. ध्यान दें, पेसमेकर, कोई इम्प्लांट, या शरीर में धातु हो, तो पहले ज़रूर बताएं. बंद जगह से डर लगता हो, तो भी बताएं.",
 "प्रेगनेंसी हो सकती है, तो हर स्कैन से पहले बताएं. ज़रूरत हो, तो डॉक्टर अक्सर एम आर आई चुनते हैं. कौन सी जांच होगी, यह डॉक्टर आपके लक्षण, इमरजेंसी, और सुरक्षा देखकर तय करते हैं. बिना ज़रूरत, बार बार स्कैन न करवाएं.",
 close_voice("आपने कभी एक्स रे, सी टी, या एम आर आई करवाया है? कौन सा?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/imgr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/img_{i}.wav"],check=True); f=f"/tmp/img_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/img_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
